dex') }}">← Results</a><button class="print" onclick="window.print()">Print</button><button class="download" onclick="window.print()">Download / Save PDF</button></div><div class="sheet"><div class="header"><img class="logo" src="{{ asset('images/logo.png') }}"><div class="school">{{ $school?->school_name ?: 'C-Net Pathshala' }}</div><div class="subtitle"><strong>{{ $student->branch?->name ?: 'Campus not assigned' }}</strong></div>@if($student->branch?->address || $school?->address)<div class="subtitle">{{ $student->branch?->address ?: $school->address }}</div>@endif@if($student->branch?->phone || $student->branch?->email)<div class="subtitle">{{ $student->branch?->phone ?: '—' }} @if($student->branch?->email) · {{ $student->branch->email }}@endif</div>@endif<div class="title">STUDENT REPORT CARD</div><div style="clear:both"></div></div><div class="info"><div><b>Student Name:</b> {{ $student->user->name }}</div><div><b>Admission No.:</b> {{ $student->admission_no }}</div><div><b>Campus:</b> {{ $student->branch?->name ?: '—' }}</div><div><b>Class:</b> {{ $student->class_name ?: '—' }}</div><div><b>Section:</b> {{ $student->section ?: '—' }}</div><div><b>Roll No.:</b> {{ $student->roll_no ?: '—' }}</div><div><b>Session:</b> {{ $school?->academic_session ?: '—' }}</div><div><b>Exam:</b> {{ $exam }}</div></div><table><thead><tr><th>S.No.</th><th>Subject</th><th>Max Marks</th><th>Obtained</th><th>%</th><th>Remark</th></tr></thead><tbody>@foreach($results as $row)@php($pct=(float)$row->max_marks>0?round(((float)$row->marks_obtained/(float)$row->max_marks)*100,1):0)<tr><td>{{ $loop->iteration }}</td><td>{{ $row->subject }}</td><td>{{ number_format((float)$row->max_marks,2) }}</td><td>{{ number_format((float)$row->marks_obtained,2) }}</td><td>{{ $pct }}%</td><td>{{ $row->remark ?: '—' }}</td></tr>@endforeach<tr style="font-weight:bold;background:#eef3f9"><td colspan="2">TOTAL</td><td>{{ number_format($summary['total'],2) }}</td><td>{{ number_format($summary['obtained'],2) }